function scratchBody(){const pending=state.pending,b=catalog.find(b=>b.id===pending.bottle);return `<div class="scratch-window-heading"><span class="eyebrow">${esc(pending.packName??'ZAPISANA ZDRAPKA')}</span><h2 title="${esc(b.name)}">${pending.revealed?esc(b.name.replace('Johnnie Walker ','')):'Odkryj swój drop.'}</h2></div><div class="scratch-stage">${photo(b,true)}${pending.revealed?'':'<canvas id="scratch" width="400" height="360"></canvas><div class="scratch-coin" aria-hidden="true"><span>€</span></div>'}</div><div class="scratch-outcome"><p class="scratch-instruction" ${pending.revealed?'hidden':''}>Przesuwaj monetę po srebrnej warstwie.<br><small>Zamknij ×, aby odłożyć butelkę do kolekcji.</small></p><div class="reward-controls" aria-hidden="${!pending.revealed}"><div class="reward-stats"><span><small>RYNEK</small>${money(value(state,b))}</span><span><small>QUICK SELL</small>${money(quickValue(state,b))}</span><span class="${quickValue(state,b)>=pending.cost?'positive':'negative'}"><small>WYNIK</small>${money(quickValue(state,b)-pending.cost)}</span></div><div class="scratch-actions"><button id="keep">Na półkę</button><button data-scratch-sell>Sprzedaj · ${money(quickValue(state,b))}</button>${b.kind!=='voucher'?'<button class="ghost" data-scratch-auction>🔨 Aukcja</button>':''}</div></div></div>`;}
function openScratchWindow(){if(!state.pending)return;if(scratchDialog?.isConnected){scratchDialog.focus();return;}const uid=state.pending.uid;scratchDialog=modal('<div class="scratch-window-body">'+scratchBody()+'</div>','scratch-play-dialog'+(state.pending.revealed?'':' covered'));scratchDialog.dataset.reward=state.pending.revealed?'revealed':'covered';const ownedDialog=scratchDialog;
 const stash=async()=>{if(ownedDialog.dataset.closing)return;ownedDialog.dataset.closing='true';ownedDialog.querySelector('[data-close]').disabled=true;while(busy)await new Promise(resolve=>requestAnimationFrame(resolve));if(state.pending?.uid===uid){if(!await act({type:'stashScratch',uid})){delete ownedDialog.dataset.closing;ownedDialog.querySelector('[data-close]').disabled=false;return;}toast('🥃 Butelka jest w Twojej kolekcji.');}if(ownedDialog.open)ownedDialog.close();};
 ownedDialog.querySelector('[data-close]').onclick=stash;ownedDialog.oncancel=e=>{e.preventDefault();stash();};ownedDialog.onclose=()=>{endDrag?.();ownedDialog.remove();if(scratchDialog===ownedDialog)scratchDialog=null;};bindScratchWindow();}
function syncScratchWindow(){if(!scratchDialog)return;if(!state.pending){const d=scratchDialog;scratchDialog=null;d.close();return;}const phase=state.pending.revealed?'revealed':'covered';if(scratchDialog.dataset.reward!==phase){endDrag?.();scratchDialog.dataset.reward=phase;scratchDialog.classList.remove('covered');setText(scratchDialog.querySelector('.scratch-window-heading h2'),catalog.find(b=>b.id===state.pending.bottle).name.replace('Johnnie Walker ',''));scratchDialog.querySelector('.reward-controls').setAttribute('aria-hidden','false');scratchDialog.querySelector('.scratch-instruction').hidden=true;const cover=scratchDialog.querySelector('#scratch');if(cover){cover.style.pointerEvents='none';if(matchMedia('(prefers-reduced-motion: reduce)').matches)cover.remove();else{const animation=cover.animate([{opacity:1},{opacity:0}],{duration:160,fill:'forwards'});animation.onfinish=()=>cover.remove();}}scratchDialog.querySelector('.scratch-coin')?.remove();}}
function bindScratchWindow(){if(!scratchDialog)return;mountBottleArt(scratchDialog);const keep=scratchDialog.querySelector('#keep');if(keep)keep.onclick=()=>act({type:'keep'});const sell=scratchDialog.querySelector('[data-scratch-sell]');if(sell)sell.onclick=()=>{const b=catalog.find(b=>b.id===state.pending.bottle);if(value(state,b)<10000||confirm('Sprzedać za '+money(quickValue(state,b))+'?'))act({type:'sell',uid:state.pending.uid});};const auction=scratchDialog.querySelector('[data-scratch-auction]');if(auction)auction.onclick=()=>auctionDialog(state.pending.uid);if(scratchDialog.querySelector('#scratch'))setupScratch();}
function modal(content,className=''){const d=document.createElement('dialog');d.className=className;d.innerHTML=`<button class="modal-close" data-close aria-label="Zamknij">×</button>${content}`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();mountBottleArt(d);return d;}
function oddsDialog(id){const p=pools(catalog,state).find(p=>p.id===id);const rows=[...p.pool].sort((a,b)=>b.chance-a.chance);const liveEv=p.pool.reduce((n,r)=>n+quickValue(state,catalog.find(b=>b.id===r.id))*r.chance,0);const d=modal(`<div class="odds-heading" style="--ticket:${p.color}"><span>${p.icon}</span><div><small>${p.pool.length} PRAWDZIWYCH WYDAŃ</small><h2>${p.name}</h2></div><b>${money(p.price)}</b></div>${p.starterDiscount?'<div class="odds-intro">🎟️ Bon −5 € na jeden pierwszy zestaw startowy.</div>':''}<div class="odds-summary"><span><small>GWARANTOWANE</small>1 butelka</span><span><small>EV QUICK SELL TERAZ</small>${money(liveEv)}</span><span><small>SUMA SZANS</small>100%</span></div><div class="odds-perks">🍀 Nos kolekcjonera: ${upgradeLevel(state,'luck')}/3 · Quick Sell ${Math.round(upgradeValue(state,'quicksell')*100)}%</div><label class="odds-search">${icon('inventory')}<input type="search" placeholder="Znajdź wydanie…" aria-label="Filtruj nagrody"></label><div class="odds-list">${rows.map(r=>{const b=catalog.find(b=>b.id===r.id);return `<article class="odds-row" data-name="${esc(b.name.toLowerCase())}">${photo(b)}<div><span class="rarity">${b.rarity}</span><h3>${esc(b.name.replace('Johnnie Walker ',''))}</h3><small>${state.items.some(x=>x.bottle===b.id&&x.status!=='sold')?'✓ W KOLEKCJI · ':''}${money(value(state,b))} · Quick Sell ${money(quickValue(state,b))}</small><div class="chance-bar"><i style="width:${Math.max(.6,r.chance*100)}%;background:${p.color}"></i></div></div><strong>${(r.chance*100).toFixed(r.chance<.001?4:2)}%</strong></article>`;}).join('')}</div><div class="odds-footer">Szanse uwzględniają kupiony poziom Nosa kolekcjonera. Nie zależą od salda ani historii strat. EV to średnia, nie gwarancja.</div>`,'odds-dialog');d.querySelector('input').oninput=e=>{d.querySelectorAll('.odds-row').forEach(row=>row.hidden=!row.dataset.name.includes(e.target.value.trim().toLowerCase()));};}
function auctionArchive(){const finished=[...state.auctions].filter(a=>a.status!=='active').reverse();const d=modal(`<div class="eyebrow">ALBUM LICYTACJI · ${finished.length}</div><h2>Archiwum <em>aukcji.</em></h2><div class="auction-archive-list">${finished.map(a=>{const b=catalog.find(b=>b.id===a.bottle);return `<article class="archive-lot" data-archive-lot="${a.uid}">${photo(b)}<div><span class="archive-outcome ${a.status}">${a.status==='sold'?'✓ SPRZEDANA':'↩ WRÓCIŁA DO KOLEKCJI'}</span><h3>${esc(b.name.replace('Johnnie Walker ',''))}</h3><small>${a.bids.length} ofert · ${a.minutes??'?'} min</small></div><div class="archive-result"><strong>${a.status==='sold'?'+'+money(Math.floor(a.bid*.95)):'—'}</strong><button class="text" data-log="${a.uid}">Historia ${icon('arrow')}</button></div></article>`;}).join('')||'<div class="archive-empty">📚<h3>Tu trafią zakończone licytacje.</h3></div>'}</div>`,'auction-archive-dialog');d.querySelectorAll('[data-log]').forEach(el=>el.onclick=()=>auctionLog(+el.dataset.log));}
function collectionHud(){const owned=state.items.filter(x=>x.status!=='sold'&&x.bottle!==voucher.id),unique=new Set(owned.map(x=>x.bottle));return `<section class="collection-hud"><div class="album-emblem">📖</div><div class="album-completion"><span>TWÓJ ALBUM</span><b>${unique.size}<small>/ ${bottles.length} wydań</small></b><div><i style="width:${unique.size/bottles.length*100}%"></i></div></div><div class="album-rarities">${[['Common','⚪'],['Uncommon','🟢'],['Rare','🔵'],['Epic','🟣'],['Legendary','🟡'],['Mythic','🔴']].map(([rarity,emoji])=>`<span title="${rarity}">${emoji}<b>${owned.filter(x=>catalog.find(b=>b.id===x.bottle)?.rarity===rarity).length}</b></span>`).join('')}</div></section>`;}
function auctionLog(uid){const a=state.auctions.find(a=>a.uid===uid);modal(`<div class="eyebrow">PRZEBIEG LICYTACJI</div><h2>${esc(catalog.find(b=>b.id===a.bottle).name)}</h2><div class="bid-log">${a.bids.map((bid,i)=>`<div><span>🔨</span><p><b>Bot-kolekcjoner #${i+1}</b><small>Notowanie ${bid.tick}</small></p><strong>${money(bid.bid)}</strong></div>`).join('')||'<div class="auction-no-bids">⌛ Brak ofert. Butelka wróci do kolekcji, jeśli nikt nie zalicytuje.</div>'}</div><p class="muted">Prowizja po sprzedaży: 5%.</p>`,'auction-log-dialog');}
function auctionDialog(uid){const x=state.items.find(x=>x.uid===uid),b=catalog.find(b=>b.id===x.bottle);const d=modal(`<form><div class="auction-setup-art">${photo(b)}<span>🔨</span></div><h2>${esc(b.name.replace('Johnnie Walker ',''))}</h2><div class="auction-reference">Rynek ${money(value(state,b))} <span>·</span> Quick Sell ${money(quickValue(state,b))}</div><div class="auction-inputs"><label>Cena startowa (€)<input name="start" type="number" min="0.01" step="0.01" value="${(Math.round(value(state,b)*.94)/100).toFixed(2)}" required></label><label>Buy Now (€)<input name="buy" type="number" min="0.01" step="0.01" placeholder="Opcjonalnie"></label></div><div class="duration-tiles">${[1,5,15].map((n,i)=>`<label><input type="radio" name="minutes" value="${n}" ${i===0?'checked':''}><span>⌛<b>${n} min</b></span></label>`).join('')}</div><div class="auction-demand"><b data-demand></b><span data-demand-note></span><small class="projected-net">Na konto przy cenie startowej: <b data-net></b></small></div><p class="muted">Prowizja 5%. Szacunek zainteresowania nie gwarantuje sprzedaży.</p><button class="auction-submit">Rozpocznij aukcję</button></form>`,'auction-setup');const estimate=()=>{const f=d.querySelector('form'),start=Math.round(+f.elements.start.value*100),minutes=+new FormData(f).get('minutes'),x=auctionEstimate(value(state,b),start,minutes);setText(d.querySelector('[data-net]'),money(Math.floor(start*.95)));setText(d.querySelector('[data-demand]'),'👥 Szansa oferty: około '+Math.round(x.chance*100)+'%');setText(d.querySelector('[data-demand-note]'),start>value(state,b)?'Cena powyżej rynku — kolekcjonerzy mogą odpuścić.':'Cena konkurencyjna względem rynku.');};d.querySelector('form').addEventListener('input',estimate);estimate();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(await act({type:'auction',uid,start:Math.round(+f.get('start')*100),buyNow:Math.round(+f.get('buy')*100),minutes:+f.get('minutes')})){d.close();tab='Auctions';render();}};}
function pointer(canvas,move,onHover){let last=null,rect=null,queue=[],frame=0,pointerId;const position=e=>({x:(e.clientX-rect.left)*canvas.width/rect.width,y:(e.clientY-rect.top)*canvas.height/rect.height});
 function flush(){frame=0;const steps=queue;queue=[];for(const args of steps)move(...args);}
 const finish=()=>{if(frame)cancelAnimationFrame(frame);flush();last=null;rect=null;canvas.parentElement?.classList.remove('scratching');document.documentElement.classList.remove('game-dragging');if(pointerId!==undefined&&canvas.hasPointerCapture(pointerId))canvas.releasePointerCapture(pointerId);if(endDrag===finish)endDrag=null;};
 canvas.onpointerdown=e=>{if(!e.isPrimary||e.button!==0)return;e.preventDefault();endDrag?.();rect=canvas.getBoundingClientRect();last={...position(e),time:performance.now()};pointerId=e.pointerId;canvas.setPointerCapture(pointerId);canvas.parentElement.classList.add('scratching');document.documentElement.classList.add('game-dragging');getSelection()?.removeAllRanges();endDrag=finish;onHover?.(last,rect,true);};
 canvas.onpointermove=e=>{if(!e.isPrimary||last&&e.pointerId!==pointerId)return;if(!last){if(onHover){rect=canvas.getBoundingClientRect();onHover(position(e),rect,false);}return;}e.preventDefault();const p=position(e),now=performance.now(),distance=Math.hypot(p.x-last.x,p.y-last.y);if(distance>1){queue.push([p,last,Math.min(now-last.time,60),distance]);last={...p,time:now};onHover?.(p,rect,true);if(!frame)frame=requestAnimationFrame(flush);}};
 canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=e=>{if(last&&e.pointerId===pointerId)finish();};
 canvas.addEventListener('dragstart',e=>e.preventDefault());
}
function setupWash(){const canvas=document.querySelector('#wash'),ctx=canvas.getContext('2d');let activeMs=0,distance=0,done=false,lastSound=0,spongePoint=null,progress=0,paintProgress=-1;let rules=washRules(state),workId=state.workId;const makeDirt=()=>Array.from({length:48},(_,i)=>({x:145+(i%8)*31+Math.sin(i*9)*7,y:145+Math.floor(i/8)*34+Math.cos(i*5)*7,left:1}));let dirt=makeDirt();workController={reset(next){if(!canvas.isConnected)return;rules=washRules(next);workId=next.workId;activeMs=0;distance=0;done=false;spongePoint=null;progress=0;dirt=makeDirt();paintProgress=-1;document.querySelector('#progress').style.transform='scaleX(0)';setText(document.querySelector('#wash-label'),'Czystość 0%');canvas.parentElement.classList.add('glass-success');setTimeout(()=>canvas.parentElement.classList.remove('glass-success'),450);}};function draw(){drawWashScene(ctx,{dirt,sponge:spongePoint,progress,radius:rules.radius,time:performance.now()});const percent=Math.floor(progress*100);if(percent!==paintProgress){paintProgress=percent;document.querySelector('#progress').style.transform=`scaleX(${progress})`;setText(document.querySelector('#wash-label'),`Czystość ${percent}%`);}}
let lastFrame=0;function animate(now){if(!canvas.isConnected)return;if(!document.hidden&&now-lastFrame>=(canvas.parentElement.classList.contains('scratching')?16:100)){draw();lastFrame=now;}requestAnimationFrame(animate);}requestAnimationFrame(animate);pointer(canvas,(p,last,ms,dist)=>{if(done)return;spongePoint=p;let touched=false;for(const spot of dirt){const dx=p.x-last.x,dy=p.y-last.y;const t=Math.max(0,Math.min(1,((spot.x-last.x)*dx+(spot.y-last.y)*dy)/(dx*dx+dy*dy)));if(Math.hypot(spot.x-last.x-t*dx,spot.y-last.y-t*dy)<rules.radius){spot.left=Math.max(0,spot.left-ms/rules.cleanMs);touched=true;}}if(touched){if(performance.now()-lastSound>300){sound(true);lastSound=performance.now();}activeMs+=ms;distance+=Math.min(dist,80);}const coverage=1-dirt.reduce((n,d)=>n+d.left,0)/dirt.length;progress=Math.min(coverage/rules.coverage,activeMs/rules.activeMs,distance/rules.distance,1);if(coverage>=rules.coverage&&activeMs>=rules.activeMs&&distance>=rules.distance){done=true;const earned=rules.reward;act({type:'tick'},{coverage,activeMs,distance,workId}).then(ok=>{if(ok)toast(`🫧 +${money(earned)} · Kryształowy błysk!`);else done=false;});}});}
function setupScratch(){const canvas=document.querySelector('#scratch'),ctx=canvas.getContext('2d');const g=ctx.createLinearGradient(0,0,400,360);g.addColorStop(0,'#6543bd');g.addColorStop(.4,'#d8c6ff');g.addColorStop(.6,'#9871de');g.addColorStop(1,'#e9dfff');ctx.fillStyle=g;ctx.fillRect(0,0,400,360);ctx.fillStyle='#443b2e';ctx.textAlign='center';ctx.font='58px Georgia';ctx.fillText('✦',200,165);ctx.font='14px sans-serif';ctx.fillText('ZDRAP I ODKRYJ',200,215);const radius=upgradeValue(state,'coin'),coin=canvas.parentElement.querySelector('.scratch-coin'),mask=createScratchMask(400,360);coin.style.setProperty('--coin-size',radius*2+'px');const rewardUID=state.pending.uid;let done=false,lastSound=0,hoverFrame=0,hoverPoint;
 const follow=(p,rect)=>{hoverPoint={x:p.x/400*rect.width,y:p.y/360*rect.height};if(!hoverFrame)hoverFrame=requestAnimationFrame(()=>{hoverFrame=0;if(!coin.isConnected)return;coin.style.transform=`translate3d(${hoverPoint.x}px,${hoverPoint.y}px,0) translate(-50%,-50%) rotate(-18deg)`;coin.classList.add('visible');});};canvas.onpointerleave=()=>coin.classList.remove('visible');
 pointer(canvas,(p,last)=>{if(done)return;ctx.globalCompositeOperation='destination-out';ctx.lineWidth=radius*2;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();if(performance.now()-lastSound>300){sound(true);lastSound=performance.now();}if(mask.erase(last,p,radius)>=.7){done=true;const reveal=async()=>{while(busy)await new Promise(resolve=>requestAnimationFrame(resolve));if(state.pending?.uid!==rewardUID)return;if(!await act({type:'reveal'}))done=false;};reveal();}},follow);
}

try{state=await transact(catalog);render();if(state.tutorial){const d=document.createElement('dialog');d.innerHTML='<div class="tutorial-icons">🧽 → 🥃 → 🎟️</div><h1>Z baru na <em>szczyt.</em></h1><p>Masz 10 €. Umyj pierwszy kieliszek (~2 s), zgarnij 1,50 € i odbierz Red Label. Misje finansują kolejne dropy!</p><p class="muted">Fikcyjna waluta. Zdrapki mogą przynosić straty.</p><button>Zaczynamy →</button>';document.body.append(d);d.showModal();d.querySelector('button').onclick=()=>{d.remove();act({type:'tutorial'});};}}catch(e){root.textContent='Nie można otworzyć zapisu IndexedDB: '+e.message;}
setInterval(async()=>{if(busy)return;try{state=await transact(catalog,undefined,undefined,{fullHistory:tab==='Market Charts'});refreshLive();}catch(e){toast(e.message);}},5000);

setInterval(()=>document.querySelectorAll('[data-end]').forEach(el=>el.textContent=timeLeft(+el.dataset.end)),1000);
